/**
 * A tiny software raster image + drawing library.
 *
 * It is used to paint every texture in this project from code: no image files
 * are downloaded, every pixel is generated by the routines below.
 *
 * Conventions
 * -----------
 * - RGBA8, straight (non-premultiplied) alpha, `data` is row-major with
 *   row 0 = TOP row (like a canvas / PNG).
 * - `sample(u, v)` uses GL style UVs: `v = 0` is the BOTTOM row.
 * - Colours are `[r, g, b, a]` with 0..255 components, or `[r, g, b]` (opaque)
 *   or a hex string like `'#1b3f8f'`. A scalar alpha is always honoured, so a
 *   source colour with `a = 128` paints at 50 % coverage.
 */

const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
const lerp = (a, b, t) => a + (b - a) * t;

/** Parse `'#rgb'`, `'#rrggbb'`, `'#rrggbbaa'`, `[r,g,b(,a)]` or `'rgb(...)'`. */
export function toRGBA(color, alphaScale = 1) {
  if (typeof color === 'string') {
    let s = color.trim();
    if (s.startsWith('rgb')) {
      const nums = s.replace(/[^0-9.,]/g, '').split(',').map(Number);
      // the fourth component is a 0..1 alpha for `rgba(...)`, 0..255 otherwise
      let a = nums.length > 3 ? nums[3] : 255;
      if (a <= 1) a *= 255;
      return [nums[0] | 0, nums[1] | 0, nums[2] | 0, Math.round(a * alphaScale)];
    }
    if (s.startsWith('#')) s = s.slice(1);
    if (s.length === 3) s = s.split('').map((c) => c + c).join('');
    if (s.length === 6) s += 'ff';
    const n = parseInt(s, 16);
    return [(n >>> 24) & 255, (n >>> 16) & 255, (n >>> 8) & 255, Math.round((n & 255) * alphaScale)];
  }
  if (Array.isArray(color)) {
    return [color[0] | 0, color[1] | 0, color[2] | 0, Math.round((color[3] ?? 255) * alphaScale)];
  }
  throw new Error(`unsupported colour: ${color}`);
}

/** Deterministic 32-bit PRNG (mulberry32) so textures are reproducible. */
export function makeRandom(seed = 1) {
  let a = seed >>> 0;
  return function random() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Smooth 2D value noise, used for dirt / brushed metal / fabric. */
export function makeNoise2D(seed = 7) {
  const random = makeRandom(seed);
  const size = 256;
  const grid = new Float32Array(size * size);
  for (let i = 0; i < grid.length; i++) grid[i] = random();
  const at = (x, y) => grid[(y & 255) * size + (x & 255)];
  const fade = (t) => t * t * (3 - 2 * t);
  return function noise(x, y) {
    const xi = Math.floor(x);
    const yi = Math.floor(y);
    const tx = fade(x - xi);
    const ty = fade(y - yi);
    return lerp(lerp(at(xi, yi), at(xi + 1, yi), tx), lerp(at(xi, yi + 1), at(xi + 1, yi + 1), tx), ty);
  };
}

/** Fractal (multi octave) noise in 0..1. */
export function fbm(noise, x, y, octaves = 4, gain = 0.5, lacunarity = 2) {
  let sum = 0;
  let amp = 1;
  let norm = 0;
  let fx = x;
  let fy = y;
  for (let o = 0; o < octaves; o++) {
    sum += amp * noise(fx, fy);
    norm += amp;
    amp *= gain;
    fx *= lacunarity;
    fy *= lacunarity;
  }
  return sum / norm;
}
export class Image {
  constructor(width, height, fill = [0, 0, 0, 0]) {
    this.width = width;
    this.height = height;
    this.data = new Uint8ClampedArray(width * height * 4);
    this.fill(fill);
  }

  clone() {
    const copy = new Image(this.width, this.height, [0, 0, 0, 0]);
    copy.data.set(this.data);
    return copy;
  }

  inBounds(x, y) {
    return x >= 0 && y >= 0 && x < this.width && y < this.height;
  }

  /** Read a pixel, `[r,g,b,a]`, alpha 0..255. */
  get(x, y) {
    x |= 0;
    y |= 0;
    if (!this.inBounds(x, y)) return [0, 0, 0, 0];
    const i = (y * this.width + x) * 4;
    return [this.data[i], this.data[i + 1], this.data[i + 2], this.data[i + 3]];
  }

  /** Overwrite a pixel (no blending). */
  set(x, y, color) {
    x = Math.round(x);
    y = Math.round(y);
    if (!this.inBounds(x, y)) return this;
    const [r, g, b, a] = toRGBA(color);
    const i = (y * this.width + x) * 4;
    this.data[i] = r;
    this.data[i + 1] = g;
    this.data[i + 2] = b;
    this.data[i + 3] = a;
    return this;
  }

  /** Source-over alpha composite of `color` onto the pixel, `coverage` in 0..1. */
  blend(x, y, color, coverage = 1) {
    x = Math.round(x);
    y = Math.round(y);
    if (!this.inBounds(x, y) || coverage <= 0) return this;
    const [r, g, b, a] = toRGBA(color, coverage);
    if (a === 0) return this;
    const sa = a / 255;
    const i = (y * this.width + x) * 4;
    const da = this.data[i + 3] / 255;
    const outA = sa + da * (1 - sa);
    if (outA <= 0) {
      this.data[i] = this.data[i + 1] = this.data[i + 2] = this.data[i + 3] = 0;
      return this;
    }
    this.data[i] = (r * sa + this.data[i] * da * (1 - sa)) / outA;
    this.data[i + 1] = (g * sa + this.data[i + 1] * da * (1 - sa)) / outA;
    this.data[i + 2] = (b * sa + this.data[i + 2] * da * (1 - sa)) / outA;
    this.data[i + 3] = outA * 255;
    return this;
  }

  /** Per pixel transform, keeps alpha unless the callback overrides it. */
  mapPixels(fn) {
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const i = (y * this.width + x) * 4;
        const out = fn(x, y, this.data[i], this.data[i + 1], this.data[i + 2], this.data[i + 3]);
        if (!out) continue;
        this.data[i] = out[0];
        this.data[i + 1] = out[1];
        this.data[i + 2] = out[2];
        if (out.length > 3) this.data[i + 3] = out[3];
      }
    }
    return this;
  }

  /** Bilinear sample with GL UVs (`v = 0` is the bottom row). */
  sample(u, v) {
    const fx = clamp(u, 0, 1) * (this.width - 1);
    const fy = (1 - clamp(v, 0, 1)) * (this.height - 1);
    const x0 = Math.floor(fx);
    const y0 = Math.floor(fy);
    const x1 = Math.min(x0 + 1, this.width - 1);
    const y1 = Math.min(y0 + 1, this.height - 1);
    const tx = fx - x0;
    const ty = fy - y0;
    const out = [0, 0, 0, 0];
    for (let c = 0; c < 4; c++) {
      const p00 = this.data[(y0 * this.width + x0) * 4 + c];
      const p10 = this.data[(y0 * this.width + x1) * 4 + c];
      const p01 = this.data[(y1 * this.width + x0) * 4 + c];
      const p11 = this.data[(y1 * this.width + x1) * 4 + c];
      out[c] = lerp(lerp(p00, p10, tx), lerp(p01, p11, tx), ty);
    }
    return out;
  }

  // ---------------------------------------------------------------- fills ---

  fill(color) {
    const [r, g, b, a] = toRGBA(color);
    for (let i = 0; i < this.data.length; i += 4) {
      this.data[i] = r;
      this.data[i + 1] = g;
      this.data[i + 2] = b;
      this.data[i + 3] = a;
    }
    return this;
  }

  /** Vertical linear gradient; `stops` = [[t, color], ...] with t in 0..1 (top to bottom). */
  gradientV(stops, x0 = 0, x1 = this.width, y0 = 0, y1 = this.height) {
    const parsed = stops.map(([t, c]) => [t, toRGBA(c)]);
    const ya = Math.max(0, Math.round(y0));
    const yb = Math.min(this.height, Math.round(y1));
    for (let y = ya; y < yb; y++) {
      const t = (y - y0) / Math.max(1, y1 - y0 - 1);
      let a = parsed[0];
      let b = parsed[parsed.length - 1];
      for (let i = 0; i < parsed.length - 1; i++) {
        if (t >= parsed[i][0] && t <= parsed[i + 1][0]) {
          a = parsed[i];
          b = parsed[i + 1];
          break;
        }
      }
      const k = b[0] === a[0] ? 0 : (t - a[0]) / (b[0] - a[0]);
      const col = [0, 1, 2, 3].map((c) => lerp(a[1][c], b[1][c], k));
      for (let x = Math.max(0, Math.round(x0)); x < Math.min(this.width, Math.round(x1)); x++) {
        this.blend(x, y, col);
      }
    }
    return this;
  }

  fillRect(x, y, w, h, color) {
    const x0 = Math.max(0, Math.round(x));
    const y0 = Math.max(0, Math.round(y));
    const x1 = Math.min(this.width, Math.round(x + w));
    const y1 = Math.min(this.height, Math.round(y + h));
    for (let py = y0; py < y1; py++) for (let px = x0; px < x1; px++) this.blend(px, py, color);
    return this;
  }

  /** Rounded rectangle with analytic anti-aliasing (signed distance field). */
  fillRoundRect(x, y, w, h, radius, color, coverage = 1) {
    const cx = x + w / 2;
    const cy = y + h / 2;
    const hw = w / 2;
    const hh = h / 2;
    const r = Math.min(radius, hw, hh);
    const x0 = Math.max(0, Math.floor(x - 1));
    const x1 = Math.min(this.width, Math.ceil(x + w + 1));
    const y0 = Math.max(0, Math.floor(y - 1));
    const y1 = Math.min(this.height, Math.ceil(y + h + 1));
    for (let py = y0; py < y1; py++) {
      for (let px = x0; px < x1; px++) {
        const dx = Math.abs(px + 0.5 - cx) - (hw - r);
        const dy = Math.abs(py + 0.5 - cy) - (hh - r);
        const d = Math.hypot(Math.max(dx, 0), Math.max(dy, 0)) + Math.min(Math.max(dx, dy), 0) - r;
        const cov = clamp(0.5 - d, 0, 1) * coverage;
        if (cov > 0) this.blend(px, py, color, cov);
      }
    }
    return this;
  }

  /** Scanline polygon fill (no AA, use for large flat areas). */
  fillPolygon(points, color) {
    let minY = Infinity;
    let maxY = -Infinity;
    for (const p of points) {
      minY = Math.min(minY, p[1]);
      maxY = Math.max(maxY, p[1]);
    }
    const y0 = Math.max(0, Math.floor(minY));
    const y1 = Math.min(this.height - 1, Math.ceil(maxY));
    for (let py = y0; py <= y1; py++) {
      const yc = py + 0.5;
      const xs = [];
      for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
        const [xi, yi] = points[i];
        const [xj, yj] = points[j];
        if (yi === yj) continue;
        if (yc >= Math.min(yi, yj) && yc < Math.max(yi, yj)) {
          xs.push(xi + ((yc - yi) / (yj - yi)) * (xj - xi));
        }
      }
      xs.sort((a, b) => a - b);
      for (let k = 0; k + 1 < xs.length; k += 2) {
        const xa = Math.max(0, Math.ceil(xs[k] - 0.5));
        const xb = Math.min(this.width - 1, Math.floor(xs[k + 1] - 0.5));
        for (let px = xa; px <= xb; px++) this.blend(px, py, color);
      }
    }
    return this;
  }

  /** Anti-aliased polygon fill (4x4 supersampling inside the bounding box). */
  fillPolygonAA(points, color, coverage = 1) {
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    for (const p of points) {
      minX = Math.min(minX, p[0]);
      maxX = Math.max(maxX, p[0]);
      minY = Math.min(minY, p[1]);
      maxY = Math.max(maxY, p[1]);
    }
    const x0 = Math.max(0, Math.floor(minX));
    const x1 = Math.min(this.width - 1, Math.ceil(maxX));
    const y0 = Math.max(0, Math.floor(minY));
    const y1 = Math.min(this.height - 1, Math.ceil(maxY));
    const inside = (px, py) => {
      let hit = false;
      for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
        const [xi, yi] = points[i];
        const [xj, yj] = points[j];
        if (yi > py !== yj > py && px < ((xj - xi) * (py - yi)) / (yj - yi) + xi) hit = !hit;
      }
      return hit;
    };
    for (let py = y0; py <= y1; py++) {
      for (let px = x0; px <= x1; px++) {
        let hits = 0;
        for (let sy = 0; sy < 4; sy++) {
          for (let sx = 0; sx < 4; sx++) {
            if (inside(px + (sx + 0.5) / 4, py + (sy + 0.5) / 4)) hits++;
          }
        }
        if (hits) this.blend(px, py, color, (hits / 16) * coverage);
      }
    }
    return this;
  }

  /** Anti-aliased thick line segment with round caps. */
  line(x0, y0, x1, y1, color, width = 1, coverage = 1) {
    const r = width / 2;
    const bx0 = Math.max(0, Math.floor(Math.min(x0, x1) - r - 1));
    const bx1 = Math.min(this.width - 1, Math.ceil(Math.max(x0, x1) + r + 1));
    const by0 = Math.max(0, Math.floor(Math.min(y0, y1) - r - 1));
    const by1 = Math.min(this.height - 1, Math.ceil(Math.max(y0, y1) + r + 1));
    const dx = x1 - x0;
    const dy = y1 - y0;
    const len2 = dx * dx + dy * dy;
    for (let py = by0; py <= by1; py++) {
      for (let px = bx0; px <= bx1; px++) {
        const cx = px + 0.5 - x0;
        const cy = py + 0.5 - y0;
        const t = len2 === 0 ? 0 : clamp((cx * dx + cy * dy) / len2, 0, 1);
        const d = Math.hypot(cx - t * dx, cy - t * dy) - r;
        const cov = clamp(0.5 - d, 0, 1) * coverage;
        if (cov > 0) this.blend(px, py, color, cov);
      }
    }
    return this;
  }

  /** Anti-aliased stroked polyline. */
  polyline(points, color, width = 1, coverage = 1) {
    for (let i = 0; i + 1 < points.length; i++) {
      this.line(points[i][0], points[i][1], points[i + 1][0], points[i + 1][1], color, width, coverage);
    }
    return this;
  }

  /** Anti-aliased filled ellipse. */
  ellipse(cx, cy, rx, ry, color, coverage = 1) {
    const x0 = Math.max(0, Math.floor(cx - rx - 1));
    const x1 = Math.min(this.width - 1, Math.ceil(cx + rx + 1));
    const y0 = Math.max(0, Math.floor(cy - ry - 1));
    const y1 = Math.min(this.height - 1, Math.ceil(cy + ry + 1));
    for (let py = y0; py <= y1; py++) {
      for (let px = x0; px <= x1; px++) {
        const nx = (px + 0.5 - cx) / rx;
        const ny = (py + 0.5 - cy) / ry;
        const d = (Math.hypot(nx, ny) - 1) * Math.min(rx, ry);
        const cov = clamp(0.5 - d, 0, 1) * coverage;
        if (cov > 0) this.blend(px, py, color, cov);
      }
    }
    return this;
  }

  circle(cx, cy, r, color, coverage = 1) {
    return this.ellipse(cx, cy, r, r, color, coverage);
  }

  /** Blit another image with alpha blending at an integer offset. */
  drawImage(src, dx, dy, coverage = 1) {
    for (let y = 0; y < src.height; y++) {
      for (let x = 0; x < src.width; x++) {
        const [r, g, b, a] = src.get(x, y);
        if (a === 0) continue;
        this.blend(dx + x, dy + y, [r, g, b, a], coverage);
      }
    }
    return this;
  }

  /** Mirror the left half onto the right half (for symmetric faces). */
  mirrorX() {
    const half = Math.floor(this.width / 2);
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < half; x++) {
        const src = this.get(x, y);
        this.set(this.width - 1 - x, y, src);
      }
    }
    return this;
  }

  /** Fine grain / noise overlay: `amount` in 0..1. */
  grain(amount = 0.04, seed = 3) {
    const random = makeRandom(seed);
    for (let y = 0; y < this.height; y++) {
      for (let x = 0; x < this.width; x++) {
        const i = (y * this.width + x) * 4;
        const n = (random() - 0.5) * 255 * amount;
        this.data[i] = clamp(this.data[i] + n, 0, 255);
        this.data[i + 1] = clamp(this.data[i + 1] + n, 0, 255);
        this.data[i + 2] = clamp(this.data[i + 2] + n, 0, 255);
      }
    }
    return this;
  }

  /** Road grime that fades in from one edge; `edge` is 'top' | 'bottom'. */
  grime(edge = 'bottom', strength = 0.35, seed = 11, scale = 5) {
    const noise = makeNoise2D(seed);
    for (let y = 0; y < this.height; y++) {
      const t = edge === 'bottom' ? 1 - y / (this.height - 1) : y / (this.height - 1);
      for (let x = 0; x < this.width; x++) {
        const n = fbm(noise, (x / this.width) * scale * 4, (y / this.height) * scale, 4);
        const a = clamp((t - 0.55) / 0.45, 0, 1) * strength * (0.4 + n);
        if (a <= 0) continue;
        const i = (y * this.width + x) * 4;
        this.data[i] = lerp(this.data[i], 26, a);
        this.data[i + 1] = lerp(this.data[i + 1], 24, a);
        this.data[i + 2] = lerp(this.data[i + 2], 22, a);
      }
    }
    return this;
  }
}

